import{_ as a,c as o,o as s,ah as n,ao as t,ap as r}from"./chunks/framework.Dq2_gudl.js";const h=JSON.parse('{"title":"Ni un gorrión es olvidado — nunca pasó desapercibido","description":"Jesús dijo que ni un gorrión cae sin que el Padre lo sepa. Qué dicen Mateo y los Salmos sobre el cuidado de Dios hacia los animales.","frontmatter":{"title":"Ni un gorrión es olvidado — nunca pasó desapercibido","description":"Jesús dijo que ni un gorrión cae sin que el Padre lo sepa. Qué dicen Mateo y los Salmos sobre el cuidado de Dios hacia los animales."},"headers":[],"relativePath":"es/pets-in-heaven/not-one-sparrow-forgotten.md","filePath":"es/pets-in-heaven/not-one-sparrow-forgotten.md"}'),i={name:"es/pets-in-heaven/not-one-sparrow-forgotten.md"};function l(d,e,u,p,c,m){return s(),o("div",null,[...e[0]||(e[0]=[n('<div class="pl-quote"><p>«Era solo un animal pequeño. ¿Lo recordará el mundo? ¿O solo yo?»</p><p class="pl-quote-soft">Jesús respondió esa pregunta una vez, y Su respuesta es más tierna de lo que esperamos.</p></div><section class="pl-section"><h2>1. Jesús dijo: ni un gorrión cae sin el Padre</h2><blockquote><p><strong>Mateo 10:29-31</strong></p><p>&quot;Are not two sparrows sold for a farthing? and one of them shall not fall on the ground without your Father. But the very hairs of your head are all numbered. Fear ye not therefore, ye are of more value than many sparrows.&quot;</p></blockquote><p>En tiempos de Jesús, los gorriones estaban entre las cosas más baratas que se podían comprar: dos por una monedita. Eran el tipo de vida que nadie notaba.</p><p>Y Jesús dijo: <strong>sin su Padre, ni uno de ellos cae a tierra.</strong></p><p>La palabra «caer» ahí significa muerte. Jesús está diciendo que la muerte del pájaro más barato no es un accidente que Dios no registró. Su partida es vista. Es anotada.</p><p>Si tu compañero era pequeño, de esos que el mundo llama «solo un animal», este versículo fue escrito para ti. Dios recuerda a los gorriones. No olvidará al tuyo.</p></section><section class="pl-section"><h2>2. Él lo alimentó — ni un día faltó</h2><blockquote><p><strong>Salmos 147:9</strong></p><p>&quot;He giveth to the beast his food, and to the young ravens which cry.&quot;</p></blockquote><p>David también escribió:</p><blockquote><p><strong>Salmos 36:6</strong></p><p>&quot;…O LORD, thou preservest man and beast.&quot;</p></blockquote><p>«A los hombres y a las bestias»: la palabra original abarca animales salvajes y domésticos. Dios pone a los animales en Su lista de quienes preserva, no como un detalle, sino al lado de nosotros.</p><p>¿Qué significa? Que desde su primer día hasta el último, cada comida, cada invierno, cada hora en que no estabas en casa, Dios lo estaba cuidando. Creías que lo cuidabas solo. Lo cuidabas junto con Dios.</p></section><section class="pl-section"><h2>3. Pertenece a Dios — y ese es el lugar más seguro</h2><blockquote><p><strong>Salmos 50:10-11</strong></p><p>&quot;For every beast of the forest is mine, and the cattle upon a thousand hills. I know all the fowls of the mountains: and the wild beasts of the field are mine.&quot;</p></blockquote><p>Dios dice: «Mía es toda bestia del bosque. El ganado sobre mil collados. Conozco todas las aves de los montes».</p><p>Tu mascota nunca fue propiedad tuya. Fue un regalo que Dios confió a tu cuidado. Y cuando quien da el regalo lo toma de vuelta, no lo tira a la basura: lo <strong>lleva a casa, junto a Sí mismo</strong>.</p><p>No sabes cómo lo cuida ahora, dónde está, ni si recuerda tu voz. Pero sabes en qué manos está: las manos que contaron los gorriones.</p><p class="pl-quote-soft">Si hoy solo puedes quedarte con una frase, quédate con esta:</p></section><div class="pl-quote"><p>«Nunca salió de la vista de Dios. Ni ahora.»</p></div><section class="pl-section"><h2>Una oración que puedes probar</h2><p>«Señor, gracias por confiármelo durante esos años.<br>Gracias por cuidarlo donde yo no podía ver.<br>Ya no puedo abrazarlo, pero sé que Tus manos son más grandes que las mías.<br>Por favor, cuídalo como cuidas a cada gorrión.<br>Y cuídame a mí, porque lo extraño mucho. Amén.»</p><p><a href="/es/pets-in-heaven/">← Volver a Pets in Heaven</a> ｜ Siguiente: <a href="/es/pets-in-heaven/rainbow-bridge-covenant">Más allá del Puente del Arcoíris</a></p></section><div class="pl-cta"><h2>Tiene un nombre.</h2><p>Escribe su nombre y una pequeña costumbre que solo tú conocías. Esos detalles merecen guardarse.</p><a class="pl-download" href="https://apps.apple.com/us/app/petloss-memorial-healing/id6757967412">Descargar en el App Store</a></div><div class="pl-bible"><h3>Deja que la Palabra te siga acompañando</h3><p>Todos los versículos de este artículo provienen de la Biblia. Con Rainbow Bible puedes leer las Escrituras en cualquier momento y poner un widget con el versículo del día: una pequeña luz en los días en que lo echas de menos.</p><div class="pl-bible-shots"><figure><img src="'+t+'" alt="Widget de Rainbow Bible mostrando 2 Timoteo 2:13" loading="lazy"><figcaption>Versículo del día en tu pantalla</figcaption></figure><figure><img src="'+r+'" alt="Rainbow Bible — tema Mascotas en el cielo mostrando Mateo 10:29-31" loading="lazy"><figcaption>Lee las Escrituras en Mascotas en el cielo</figcaption></figure></div><a class="pl-bible-download" href="https://apps.apple.com/app/id6756217525">Descargar Rainbow Bible en el App Store</a></div>',8)])])}const g=a(i,[["render",l]]);export{h as __pageData,g as default};
